import 'dart:async';import 'package:injectable/injectable.dart';import 'package:webitel_portal_sdk/src/domain/entities/download.dart';import 'package:webitel_portal_sdk/src/domain/entities/media_file_response.dart';import 'package:webitel_portal_sdk/src/domain/services/chat_service.dart';import 'package:webitel_portal_sdk/src/generated/portal/media.pbgrpc.dart';import 'package:webitel_portal_sdk/src/injection/injection.dart';/// Implementation of the [Download] interface, representing a file download operation.@LazySingleton(as: Download)final class DownloadImpl implements Download {  /// The ID of the file being downloaded.  final String fileId;  final String savePath;  /// The current offset in bytes of the download.  @override  int offset;  /// The subscription for the download stream.  StreamSubscription<MediaFile>? subscription;  @override  final StreamController<MediaFileResponse> onData;  late final ChatService _chatService;  // Flushes and closes the file sink of the current transfer.  Future<void> Function()? _release;  bool _paused = false;  /// Whether the download was paused and has not been resumed since.  bool get isPaused => _paused;  /// Constructs a [DownloadImpl] with the given file ID, offset, and data stream.  ///  /// [fileId] is the ID of the file being downloaded.  /// [offset] is the current offset in bytes of the download.  /// [onData] is a stream of [MediaFileResponse] providing updates on the download progress.  DownloadImpl({    this.subscription,    required this.offset,    required this.onData,    required this.fileId,    required this.savePath,  }) {    _chatService = getIt.get<ChatService>();  }  /// Pauses the download operation.  ///  /// Cancels the current subscription and flushes the bytes received so far  /// to the file, so [resume] can append to it.  @override  Future<void> pause() async {    _paused = true;    final current = subscription;    subscription = null;    await current?.cancel();    final release = _release;    _release = null;    await release?.call();  }  /// Resumes the download operation.  ///  /// Delegates the resume operation to the [ChatService].  @override  Future<void> resume() async {    _paused = false;    _chatService.resumeDownload(      fileId: fileId,      controller: onData,      offset: offset,      download: this,    );  }  /// Updates the offset of the download.  ///  /// [newOffset] is the new offset in bytes to update.  void updateOffset(int newOffset) {    offset = newOffset;  }  /// Sets the subscription for the download.  ///  /// [newSubscription] is the new [StreamSubscription] to set.  void setSubscription(StreamSubscription<MediaFile> newSubscription) {    subscription = newSubscription;  }  /// Sets the callback that flushes and closes the file sink on [pause].  void setRelease(Future<void> Function() release) {    _release = release;  }}